import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { M3_PAIRS, M3_ROLES, m3Contrast, m3Hex, m3Scheme } from "../src/m3";
import { parseTokens, THEMES, type Theme } from "../src/tokens";

const read = (path: string) => readFileSync(new URL(`../${path}`, import.meta.url), "utf8");

interface Fixture {
  snapshot: string;
  contrast: Record<Theme, { foreground: string; background: string; min: number; ratio: number }[]>;
  colors: Record<Theme, Record<string, string>>;
}

// Generated by tools/m3_fixture.py from the Python reference (tools/m3.py).
const fixture = JSON.parse(read("tests/fixtures/m3.json")) as Fixture;
const set = parseTokens(JSON.parse(read("design-system/tokens.json")));

describe("fixture", () => {
  it("was generated from the committed token snapshot", () => {
    expect(fixture.snapshot).toBe(read("design-system/VERSION").trim());
  });

  it("covers every role and pair", () => {
    for (const theme of THEMES) {
      expect(Object.keys(fixture.colors[theme]).sort()).toEqual([...M3_ROLES].sort());
      expect(fixture.contrast[theme]).toHaveLength(M3_PAIRS.length);
    }
  });
});

describe.each(THEMES)("Material 3 scheme (%s)", (theme) => {
  const scheme = m3Scheme(set, theme);

  it("matches the hex value of every role from tools/m3.py", () => {
    expect(m3Hex(scheme)).toEqual(fixture.colors[theme]);
  });

  it("matches the contrast of every pair from tools/m3.py", () => {
    const results = m3Contrast(scheme);
    expect(results.map(({ foreground, background, min }) => ({ foreground, background, min }))).toEqual(
      fixture.contrast[theme].map(({ foreground, background, min }) => ({ foreground, background, min })),
    );
    results.forEach((result, index) => {
      expect(result.ratio).toBeCloseTo(fixture.contrast[theme][index]?.ratio ?? NaN, 9);
    });
  });

  it("meets the guaranteed contrast (4.5:1 text, 3:1 outline)", () => {
    const failing = m3Contrast(scheme)
      .filter((result) => !result.ok)
      .map((result) => `${result.foreground}/${result.background} ${result.ratio.toFixed(2)} < ${result.min}`);
    expect(failing).toEqual([]);
  });
});

describe("Android.md", () => {
  // The Kotlin blocks in Android.md are the published form of the same numbers.
  const markdown = read("design-system/Android.md");
  const block = (name: string): Record<string, string> => {
    const start = markdown.indexOf(`val ${name} =`);
    const end = markdown.indexOf("\n)", start);
    const body = markdown.slice(start, end);
    return Object.fromEntries(
      [...body.matchAll(/^\s+(\w+) = Color\(0xFF([0-9A-F]{6})\),?$/gm)].map((match) => [match[1], `#${match[2]}`]),
    );
  };

  it.each([
    ["light", "PatinaLight"],
    ["dark", "PatinaDark"],
  ] as const)("lists the computed %s colours", (theme, name) => {
    expect(block(name)).toEqual(m3Hex(m3Scheme(set, theme)));
  });
});
